import { randomBytes } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { MixtapeError } from "./io.js";

/** Job ids are generated by Mixtape and checked on the way back in (no path traversal). */
export const JOB_ID = /^[a-z0-9-]{6,64}$/;

export function newJobId(hint: string): string {
  const base = hint.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "job";
  return `${base}-${randomBytes(3).toString("hex")}`;
}

export function assertJobId(id: string, kind: string): void {
  if (!JOB_ID.test(id)) throw new MixtapeError(`"${id}" is not a ${kind} job id.`);
}

export interface Paths {
  root: string;
  /** .cache/<step>/<job>/ */
  jobs: (step: "break" | "hook" | "press") => string;
  sources: string;
  structures: string;
}

export function projectPaths(root: string = process.cwd()): Paths {
  return {
    root,
    jobs: (step) => join(root, ".cache", step),
    sources: join(root, ".cache", "sources"),
    structures: join(root, "data", "structures"),
  };
}

/**
 * The source text a break job cached (transcript + ad copy), for originality checks
 * in later steps. Empty when the structure has no cache (templates, other machines).
 */
export function cachedSourceText(root: string, cacheId: string | undefined): string {
  if (!cacheId || !JOB_ID.test(cacheId)) return "";
  const dir = join(root, ".cache", "break", cacheId);
  const parts: string[] = [];
  const tx = join(dir, "transcript.json");
  if (existsSync(tx)) {
    const text = (JSON.parse(readFileSync(tx, "utf8")) as { text?: unknown }).text;
    if (typeof text === "string") parts.push(text);
  }
  const copy = join(dir, "ad_copy.txt");
  if (existsSync(copy)) parts.push(readFileSync(copy, "utf8"));
  return parts.filter(Boolean).join("\n");
}
